static char sx__str11[]="901f515";
static char sx__str12[]="unknown";
static char sx__str13[]="usage:";
static char sx__str14[]="  spectre <command> [args] | <input.sx> [options]";
static char sx__str15[]="commands:";
static char sx__str16[]="  init    <name>       Initialize a new project";
static char sx__str17[]="  fmt     <path>       Format .sx files or directories in place";
static char sx__str18[]="  critic  <path>       Point out antipatterns in .sx files";
static char sx__str19[]="  build   <config>     Build using a config from sx.mod";
static char sx__str20[]="  run     <input.sx>   Compile and immediately run a program";
static char sx__str21[]="  doc     <path>       Generate docs for a file or directory";
static char sx__str22[]="  add     <git-url>    Clone a git dependency into ./lib/ and record it";
static char sx__str23[]="  install <git-url>    Build and install a Spectre project from a repository";
static char sx__str24[]="  remove  <dep-name>   Remove a dependency by repository name";
static char sx__str25[]="  upgrade <dep-name>   Upgrade dependencies in ./lib/ to their latest HEAD";
static char sx__str26[]="  help    <topic>      Show detailed help for a command or flag";
static char sx__str27[]="  restore              Restore all dependencies from sx.mod and sx.lock into ./lib/";
static char sx__str28[]="  graph                Visualize the project dependency tree";
static char sx__str29[]="  ref                  Generate the language reference in the current directory";
static char sx__str30[]="  clean                Remove build artifacts";
static char sx__str31[]="  doctor               Show system and Spectre installation information";
static char sx__str32[]="  port-c  <file>       Translate C source into a single .sx file";
static char sx__str33[]="  bind-c  <file|dir>   Generate Spectre bindings from C headers";
static char sx__str34[]="options:";
static char sx__str35[]="  -ast                 Print the AST in a unicode tree and exit";
static char sx__str36[]="  -syntax-check        Check validity of syntax given some program";
static char sx__str37[]="  -emit-ssa            Print QBE IR to stdout and exit";
static char sx__str38[]="  -emit-shim:<file>    Write the QBE shim alongside -emit-ssa";
static char sx__str39[]="  -emit-alt            Print alternative IR to stdout and exit";
static char sx__str40[]="  -emit-asm            Print assembly to stdout and exit";
static char sx__str41[]="  -target:<os>.<arch>  Cross-compile (linux/windows, x86_64/aarch64)";
static char sx__str42[]="  -runtime:<mode>      Runtime mode: freestanding (default) or hosted";
static char sx__str43[]="  -xwin:<dir>          Specify xwin root for hosted Windows cross builds";
static char sx__str44[]="  -no-xwin             Disable automatic xwin discovery";
static char sx__str45[]="  -import-map:<file>   Extra Windows symbol-to-DLL map";
static char sx__str46[]="  -sysroot:<dir>       Target sysroot for hosted cross builds";
static char sx__str47[]="  -rt-lib:<file>       Explicit freestanding runtime archive/object";
