static char sx__str71[]="init";
static char sx__str72[]="init - Initialize a new project";
static char sx__str73[]="  spectre init [name]";
static char sx__str74[]="Creates sx.mod, sx.lock, src/main.sx and .gitignore in the current";
static char sx__str75[]="directory. The project name defaults to the current directory name.";
static char sx__str76[]="fmt";
static char sx__str77[]="fmt - Format Spectre source files";
static char sx__str78[]="  spectre fmt [-stdio] <file.sx|directory>...";
static char sx__str79[]="  -stdio      Write formatted output to stdout instead of editing in place";
static char sx__str80[]="  -h, -help   Show this help message";
static char sx__str81[]="Directories are searched recursively for .sx files. Other files are";
static char sx__str82[]="ignored. Without -stdio, files are rewritten in place.";
static char sx__str83[]="Calls, signatures and struct/type literals longer than 100";
static char sx__str84[]="characters are split across multiple lines when they can be split";
static char sx__str85[]="safely.";
static char sx__str86[]="critic";
static char sx__str87[]="critic - Point out antipatterns in Spectre source files";
static char sx__str88[]="  spectre critic [-fix] <file.sx|directory>...";
