static char sx__str90[]="Directories are searched recursively for .sx files. The exit code is";
static char sx__str91[]="non-zero when issues remain.";
static char sx__str92[]="build";
static char sx__str93[]="build - Build using a configuration from sx.mod";
static char sx__str94[]="  spectre build [config]";
static char sx__str95[]="The configuration name defaults to \"dev\".";
static char sx__str96[]="sx.mod must contain a spectre_version that matches the installed";
static char sx__str97[]="compiler, or the build is rejected. A build configuration may also";
static char sx__str98[]="define compile-time environment variables with an env { } block.";
static char sx__str99[]="install";
static char sx__str100[]="install - Build and install a Spectre project from a repository";
static char sx__str101[]="  spectre install <git-url> [-config <name>] [-shell <shell>]";
static char sx__str102[]="                [-bin-dir <dir>]";
static char sx__str103[]="  -config <name>  Build configuration to use (default: prod, then";
static char sx__str104[]="                  production, release, default, dev, then the first";
static char sx__str105[]="                  configuration in sx.mod)";
static char sx__str106[]="  -shell <shell>  Shell to configure PATH for (bash, zsh, fish,";
static char sx__str107[]="                  nushell, elvish, powershell, sh, ksh, tcsh, ...)";
static char sx__str108[]="                  Use 'all' to write every supported integration.";
static char sx__str109[]="  -bin-dir <dir>  Override the install directory";
static char sx__str110[]="  -h, -help       Show this help message";
static char sx__str111[]="The repository is cloned to a temporary directory, built with the";
static char sx__str112[]="installed Spectre compiler, and the resulting executable is copied";
static char sx__str113[]="into a Spectre-owned binary directory:";
static char sx__str114[]="  ~/.local/share/spectre/bin";
static char sx__str115[]="That directory is then added to PATH for the selected shell.";
static char sx__str116[]="run";
static char sx__str117[]="run - Compile and immediately run a program";
static char sx__str118[]="  spectre run <input.sx> [options]";
static char sx__str119[]="Compiler options after the input file are applied before running.";
static char sx__str120[]="doc";
static char sx__str121[]="doc - Generate documentation for a source file";
static char sx__str122[]="  spectre doc [path] [-o <dir>] [-md] [-read <file>]";
static char sx__str123[]="  -o <dir>     Write documentation to <dir> instead of the default";
static char sx__str124[]="  -md          Generate Markdown instead of HTML";
static char sx__str125[]="  -read <file> Use <file> (relative to the current directory) as the";
