static char sx__str2314[]="data $str_w_mode = { b \"w\", b 0 }\ndata $str_r_mode = { b \"r\", b 0 }\ndata $sx_stdin_ptr = { l 0 }\ndata $sx_stdout_ptr = { l 0 }\ndata $sx_stderr_ptr = { l 0 }\n\nfunction l $sx_stdout() {\n@start\n    %p =l loadl $sx_stdout_ptr\n    %c =w cnel %p, 0\n    jnz %c, @done, @init\n@init\n    %r =l call $fdopen(w 1, l $str_w_mode)\n    storel %r, $sx_stdout_ptr\n    ret %r\n@done\n    ret %p\n}\nfunction l $sx_stderr() {\n@start\n    %p =l loadl $sx_stderr_ptr\n    %c =w cnel %p, 0\n    jnz %c, @done, @init\n@init\n    %r =l call $fdopen(w 2, l $str_w_mode)\n    storel %r, $sx_stderr_ptr\n    ret %r\n@done\n    ret %p\n}\nfunction l $sx_stdin() {\n@start\n    %p =l loadl $sx_stdin_ptr\n    %c =w cnel %p, 0\n    jnz %c, @done, @init\n@init\n    %r =l call $fdopen(w 0, l $str_r_mode)\n    storel %r, $sx_stdin_ptr\n    ret %r\n@done\n    ret %p\n}\n\ndata $sx_argc_store = { l 0 }\ndata $sx_argv_store = { l 0 }\n\nfunction l $sx_get_args() {\n@start\n    %argc =l loadl $sx_argc_store\n    %argv =l loadl $sx_argv_store\n    %hdr =l call $malloc(l 32)\n    %cap =l mul %argc, 8\n    %buf =l call $malloc(l %cap)\n    storel %buf, %hdr\n    %len_slot =l add %hdr, 8\n    storel 0, %len_slot\n    %cap_slot =l add %hdr, 16\n    storel %argc, %cap_slot\n    %desc_slot =l add %hdr, 24\n    storel 0, %desc_slot\n    %i =l copy 0\n@args_loop\n    %done =w csgel %i, %argc\n    jnz %done, @args_done, @args_body\n@args_body\n    %off =l mul %i, 8\n    %slot =l add %argv, %off\n    %str =l loadl %slot\n    %cur_len =l loadl %len_slot\n    %boff =l mul %cur_len, 8\n    %bslot =l add %buf, %boff\n    storel %str, %bslot\n    %new_len =l add %cur_len, 1\n    storel %new_len, %len_slot\n    %i =l add %i, 1\n    jmp @args_loop\n@args_done\n    ret %hdr\n}\n\nfunction l $__sx_get_args() {\n@start\n    %r =l call $sx_get_args()\n    ret %r\n}\n\nfunction l $sxqbe_strcmp(l %a, l %b) {\n@start\n    %pa =l copy %a\n    %pb =l copy %b\n@loop\n    %ca =w loadub %pa\n    %cb =w loadub %pb\n    %d =w sub %ca, %cb\n    %ne =w cnew %d, 0\n    jnz %ne, @diff, @same\n@same\n    %z =w ceqw %ca, 0\n    jnz %z, @done, @advance\n@advance\n    %pa =l add %pa, 1\n    %pb =l add %pb, 1\n    jmp @loop\n@diff\n    %r =l extsw %d\n    ret %r\n@done\n    ret 0\n}\n\nfunction l $sxqbe_atoi(l %s) {\n@start\n    %p =l copy %s\n    %n =l copy 0\n    %sign =l copy 1\n@ws\n    %c =w loadub %p\n    %is_sp =w ceqw %c, 32\n    %is_tab =w ceqw %c, 9\n    %is_nl =w ceqw %c, 10\n    %is_vt =w ceqw %c, 11\n    %is_ff =w ceqw %c, 12\n    %is_cr =w ceqw %c, 13\n    %w1 =w or %is_sp, %is_tab\n    %w2 =w or %is_nl, %is_vt\n    %w3 =w or %is_ff, %is_cr\n    %w4 =w or %w1, %w2\n    %is_ws =w or %w4, %w3\n    jnz %is_ws, @ws_advance, @sign\n@ws_advance\n    %p =l add %p, 1\n    jmp @ws\n@sign\n    %c2 =w loadub %p\n    %is_plus =w ceqw %c2, 43\n    %is_minus =w ceqw %c2, 45\n    %is_sign =w or %is_plus, %is_minus\n    jnz %is_sign, @sign_advance, @digits\n@sign_advance\n    jnz %is_minus, @negative, @sign_done\n@negative\n    %sign =l copy -1\n@sign_done\n    %p =l add %p, 1\n    jmp @digits\n@digits\n    %c3 =w loadub %p\n    %ge0 =w cugew %c3, 48\n    %le9 =w culew %c3, 57\n    %is_digit =w and %ge0, %le9\n    jnz %is_digit, @digit_body, @done\n@digit_body\n    %d =w sub %c3, 48\n    %dl =l extuw %d\n    %n10 =l mul %n, 10\n    %n =l add %n10, %dl\n    %p =l add %p, 1\n    jmp @digits\n@done\n    %r =l mul %n, %sign\n    ret %r\n}\n\nfunction l $sxqbe_strlen(l %s) {\n@start\n    %p =l copy %s\n    %n =l copy 0\n@loop\n    %c =w loadub %p\n    %done =w ceqw %c, 0\n    jnz %done, @done, @body\n@body\n    %p =l add %p, 1\n    %n =l add %n, 1\n    jmp @loop\n@done\n    ret %n\n}\n\nfunction w $os__exit(w %code) {\n@start\n    call $exit(w %code)\n    ret 0\n}";
